import{z as i,x as l,o as r,c as C,q as s,j as n,D as a,d as A,s as o,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"软错误与 ECC 内存","description":"","frontmatter":{"title":"软错误与 ECC 内存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/soft-error-ecc.md","filePath":"cs/soft-error-ecc.md","lastUpdated":1791413859000}'),D={name:"cs/soft-error-ecc.md"};function p(d,E,c,m,h,S){const t=l("Mermaid");return r(),C("div",null,[E[2]||(E[2]=s('<h1 id="软错误与-ecc-内存" tabindex="-1">软错误与 ECC 内存 <a class="header-anchor" href="#软错误与-ecc-内存" aria-label="Permalink to &quot;软错误与 ECC 内存&quot;">​</a></h1><div class="epigraph"><p>粒子打中 SRAM 或 DRAM 电容，比特翻转而晶体管并未损坏；纠错码把可纠正的翻转从故障里分开，扫描测试看不见这一类。</p><footer>—— 据 Baumann, Soft Errors in Advanced Computer Systems, IEEE Micro 2005；Hamming 编码先修；JEDEC 与服务器内存实践 整理</footer></div><p><a href="/cs/bist">上一课</a>抓制造与部分老化硬缺陷。组成课已有<a href="/cs/dram-refresh">DRAM 刷新</a>与<a href="/cs/hamming-code">汉明码</a>。缺口是运行期 <strong>软错误（SER）</strong>：SEU 翻转存储节点，功能上像随机写，扫描链当时可能是好的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宇宙射线中子、封装 α 粒子在扩散区产生电荷，SRAM 位单元翻转阈值随工艺变低。DRAM 电容也可被扰，但机制与刷新丢失不同。缺口不是再讲 March 算法，而是：<strong>检测/纠正</strong>要做在数据通路上——ECC 旁路、寄存器文件奇偶、流水线保护。</p><p><span class="marginnote">术语翻译：软错误的「软」不是软件的软——是硬件没坏、只有信息坏了：粒子打翻一个比特，重写一遍就恢复。所以扫描测试当时测一切正常，故障却已经发生过；这与制造缺陷（硬故障）属于两套完全不同的可靠性门类。</span></p><p>SECDED（单纠正双检测）常用于缓存与 DIMM。芯片杀（chipkill）把符号分布到多个颗粒，对照后课 DRAM 组织。本课钉「软错误 ≠ 硬故障」与 ECC 的位置。</p><p><span class="marginnote">数字实例：SECDED 的开销算一下——保护 64 位数据要 8 个校验位（含一个整体偶校验位），所以服务器 DIMM 是 72 位宽对 64 位数据。每 8 字节多付 1 字节、约 12.5% 的容量税，换来「纠 1 检 2」。</span></p><h3 id="ecc-不是「bist-的另一种签名」" tabindex="-1">ECC 不是「BIST 的另一种签名」 <a class="header-anchor" href="#ecc-不是「bist-的另一种签名」" aria-label="Permalink to &quot;ECC 不是「BIST 的另一种签名」&quot;">​</a></h3><p>BIST 压缩的是测试响应；ECC 是功能数据的冗余，每拍（或每次读）算。把二者合成一种「校验」，会在该不启动 BIST 的功能路径上误插 LFSR。软错误纠正后程序继续；不可纠正则机器检查异常——OS 课再接，本课承认有 UE 信号。</p><p><span class="marginnote">Baumann, <em>IEEE Micro</em>, 2005 是软错误综述名篇。Hamming/SECDED 在信息论课已有。JEDEC DDR 规范含 ECC DIMM 的数据宽度（如 ×72）。本课不编造 FIT 数字表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：数据+校验进译码器，纠正后送 CPU，写回可选。写：编码器生成校验。部分写要先读–改–写以免校验不一致。寄存器与 FF：关键控制用三重化（TMR）或只对地址/状态奇偶。FPU 数据路径是否 ECC 是成本选择。</p>',13)),(r(),n(B,null,{default:a(()=>[o(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PART%5B%22%E7%B2%92%E5%AD%90%20%2F%20%CE%B1%22%5D%20--%3E%20SEU%5B%22%E5%AD%98%E5%82%A8%E6%AF%94%E7%89%B9%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20SEU%20--%3E%20ECC%5B%22SECDED%20%E8%AF%91%E7%A0%81%22%5D%0A%20%20ECC%20--%3E%20CE%5B%22%E7%BA%A0%E6%AD%A3%E5%B9%B6%E8%AE%B0%E5%BD%95%22%5D%0A%20%20ECC%20--%3E%20UE%5B%22%E4%B8%8D%E5%8F%AF%E7%BA%A0%E6%AD%A3%20%E2%86%92%20%E6%A3%80%E6%9F%A5%E5%BC%82%E5%B8%B8%22%5D%0A%20%20CE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%80%81%E5%8C%96%E6%98%AF%E5%8F%A6%E4%B8%80%E6%97%B6%E9%97%B4%E5%B0%BA%E5%BA%A6%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"扫描测试通常不注入粒子；SER 用加速试验与 FIT 模型估计，属可靠性工程，与 ATPG 分家。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"下一课老化（NBTI、电迁移）让延迟漂移，表现为时序违例而非单比特翻转。DRAM 组织课会看到 rank/bank 上的 ECC 布局。本课先把「运行期随机翻转」钉进数字系统课序的可靠性入口。",-1)),(r(),n(B,null,{default:a(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%AF%BB%E5%8F%96%E6%95%B0%E6%8D%AE%E5%8A%A0%E6%A0%A1%E9%AA%8C%E4%BD%8D%22%5D%20--%3E%20SY%5B%22%E9%87%8D%E7%AE%97%E6%A0%A1%E9%AA%8C%E5%BE%97%E4%BC%B4%E9%9A%8F%E5%BC%8F%22%5D%0A%20%20SY%20--%3E%20C%7B%22%E4%BC%B4%E9%9A%8F%E5%BC%8F%E6%8C%87%E5%90%91%E5%93%AA%E9%87%8C%3F%22%7D%0A%20%20C%20--%20%22%E9%9B%B6%22%20--%3E%20OK%5B%22%E6%97%A0%E9%94%99%20%E6%95%B0%E6%8D%AE%E7%9B%B4%E9%80%9A%22%5D%0A%20%20C%20--%20%22%E5%90%88%E6%B3%95%E4%BD%8D%E7%BD%AE%22%20--%3E%20FIX%5B%22%E5%8D%95%E6%AF%94%E7%89%B9%E9%94%99%20%E7%BF%BB%E8%BD%AC%E8%AF%A5%E4%BD%8D%E7%BA%A0%E6%AD%A3%E5%B9%B6%E8%AE%A1%E6%95%B0%22%5D%0A%20%20C%20--%20%22%E8%B6%8A%E7%95%8C%22%20--%3E%20DET%5B%22%E5%8F%8C%E6%AF%94%E7%89%B9%E9%94%99%20%E5%8F%AA%E6%8A%A5%E4%B8%8D%E5%8F%AF%E7%BA%A0%E6%AD%A3%22%5D%0A%20%20OK%20--%3E%20FWD%5B%22%E6%95%B0%E6%8D%AE%E9%80%81%20CPU%22%5D%0A%20%20FIX%20--%3E%20FWD%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=s('<p><span class="marginnote">这张图回答「SECDED 一次读到底怎么判」：重算校验得伴随式，零是无错、命中合法位置纠一位、越界说明至少坏两位只能上报。直觉上，校验位给每个合法码字圈出一个「半径 1」的专属邻域——落进邻域的错能拉回原位，落在邻域之间的错只能报警。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲辐射加固工艺细节，不把纠错当密码学。不进入量子计算误码。不把 ECC 内存的通道时序写完——那是 DDR 课。</p><p><span class="marginnote">常见误区：以为装了 ECC 内存就「不会错」。SECDED 只纠单比特、检双比特；同一次访问坏到第三位，照样不可纠正、机器检查异常。chipkill 解决的是「一整颗颗粒掉线」的场景，不是把错误率清零——它换的是故障覆盖面，不是物理规律。</span></p><p>后课默认：软错误是可恢复或不可纠正的随机位翻转；功能 ECC 与制造 BIST 分工。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BIST 对硬缺陷；软错误是运行期 SEU。</li><li>SECDED 在读路径纠正并报告；UE 另处理。</li><li>扫描当时通过不保证现场无翻转。</li><li>出处：Baumann, <em>IEEE Micro</em>, 2005；汉明码先修；JEDEC ECC DIMM 实践。</li></ul>',7))])}const u=i(D,[["render",p]]);export{f as __pageData,u as default};
